import random
import sqlite3

SCHEMA = """
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL);
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL,
                   currency TEXT NOT NULL, day INTEGER NOT NULL, status TEXT NOT NULL);
"""
CURRENCIES = ["EUR", "USD", "GBP", "JPY", "CHF"]
GROUPS = ['north', 'south', 'east', 'west']


class FakeRates:
    """Stands in for the remote exchange-rate service."""

    def __init__(self):
        self.calls = 0

    def lookup(self, currency, day):
        self.calls += 1
        return 8000 + (sum(map(ord, currency)) * 37 + day * 11) % 2500


class ScanList(list):
    """A list that counts how many entries membership tests and iteration touch."""

    scanned = 0

    def __contains__(self, item):
        try:
            idx = self.index(item)
        except ValueError:
            self.scanned += len(self)
            return False
        self.scanned += idx + 1
        return True

    def __iter__(self):
        for x in list.__iter__(self):
            self.scanned += 1
            yield x

    def __getitem__(self, i):
        self.scanned += 1
        return list.__getitem__(self, i)


def make_db(seed, n_parties, n_rows, n_cur, n_days, blocked_share=0.3):
    rng = random.Random(seed)
    conn = sqlite3.connect(":memory:")
    conn.executescript(SCHEMA)
    ids = rng.sample(range(100, 100 + 4 * max(n_parties, 1)), n_parties)
    for pid in ids:
        conn.execute("INSERT INTO customers VALUES (?, ?, ?)", (pid, "n%d" % pid, rng.choice(GROUPS)))
    rows = []
    for rid in range(1, n_rows + 1):
        rows.append((rid, rng.choice(ids), rng.randint(1, 9), rng.randint(50, 900), rng.choice(CURRENCIES[:n_cur]), rng.randint(1, n_days),
                     rng.choice(["paid"] * 4 + ["void"])))
    conn.executemany("INSERT INTO orders VALUES (?, ?, ?, ?, ?, ?, ?)", rows)
    conn.commit()
    blocked = [pid for pid in ids if rng.random() < blocked_share] + [rng.randint(5000, 9000) for _ in range(max(2, n_parties // 10))]
    rng.shuffle(blocked)
    return conn, blocked


def reference(conn, rates, blocked):
    skip = set(blocked)
    known = {pid: (n, g) for pid, n, g in conn.execute("SELECT id, name, region FROM customers")}
    out = {}
    for rid, owner, q, p, c, d in conn.execute("SELECT id, customer_id, qty, unit_cents, currency, day FROM orders WHERE status = 'paid' ORDER BY id"):
        if owner in skip:
            continue
        entry = out.setdefault(owner, {"customer": owner, "name": known[owner][0], "region": known[owner][1], "orders": 0, "total": 0})
        entry["orders"] += 1
        entry["total"] += q * p * rates.lookup(c, d) // 10000
    return sorted(out.values(), key=lambda e: (-e["total"], e["customer"]))


def distinct_pairs(conn):
    return len(conn.execute("SELECT DISTINCT currency, day FROM orders WHERE status = 'paid'").fetchall())

