def build_report(conn, rates, blocked):
    """Freight billed per depot in the home currency: one dict per depot, biggest total first (see README)."""
    known = store.all_depots(conn)
    blocked_ids = set(blocked)
    rate_cache = {}
    kept = []
    for _id, owner, qty, price, cur, day in store.paid_rows(conn):
        if owner in blocked_ids:
            continue
        name, group = known[owner]
        key = (cur, day)
        if key not in rate_cache:
            rate_cache[key] = rates.lookup(cur, day)
        rate = rate_cache[key]
        kept.append((owner, name, group, qty * price * rate // 10000))
    grouped = {}
    for owner, name, group, amount in kept:
        entry = grouped.get(owner)
        if entry is None:
            entry = grouped[owner] = {"depot": owner, "name": name, "zone": group, "parcels_billed": 0, "total": 0}
        entry["parcels_billed"] += 1
        entry["total"] += amount
    report = list(grouped.values())
    report.sort(key=lambda item: (-item["total"], item["depot"]))
    return report

