        for x in list.__iter__(self):
            self.scanned += 1
            yield x

    def __getitem__(self, i):
        self.scanned += 1
        return list.__getitem__(self, i)


def make_db(seed, n_parties, n_rows, n_cur, n_days, blocked_share=0.3):
